import { Component } from '@angular/core';

@Component({
  selector: 'app-admin',
  templateUrl: './admin.component.html',
  styleUrls: ['./admin.component.scss']
})
export class AdminComponent {

}
<div class="container">
  <div class="row">
    <div class="col-6">
      <qrcode
        [qrdata]="'abhimanyu'"
        [width]="256"
        [errorCorrectionLevel]="'M'"
      ></qrcode>
    </div>
    <div class="col-6">Mishra</div>
  </div>
</div>
